const std = @import("std");
const Allocator = std.mem.Allocator;
const math = std.math;

pub const Tensor = struct {
    data: []f32,
    rows: usize,
    cols: usize,

    pub fn init(allocator: Allocator, r: usize, c: usize) !Tensor {
        const d = try allocator.alloc(f32, r * c);
        @memset(d, 0.0);
        return Tensor{ .data = d, .rows = r, .cols = c };
    }

    pub fn deinit(self: *Tensor, allocator: Allocator) void {
        allocator.free(self.data);
    }

    pub fn get(self: *const Tensor, r: usize, c: usize) f32 {
        return self.data[r * self.cols + c];
    }

    pub fn set(self: *Tensor, r: usize, c: usize, val: f32) void {
        self.data[r * self.cols + c] = val;
    }
};

pub const LearnedEmbedding = struct {
    weight: Tensor,
    grad: Tensor,
    vocab_size: usize,
    dim: usize,

    pub fn init(allocator: Allocator, v_size: usize, d: usize, prng: *std.rand.DefaultPrng) !LearnedEmbedding {
        var w = try Tensor.init(allocator, v_size, d);
        var g = try Tensor.init(allocator, v_size, d);
        var i: usize = 0;
        const total = v_size * d;
        while (i < total) : (i += 1) {
            w.data[i] = (prng.random().float(f32) - 0.5) * 0.02;
        }
        return LearnedEmbedding{
            .weight = w,
            .grad = g,
            .vocab_size = v_size,
            .dim = d,
        };
    }

    pub fn deinit(self: *LearnedEmbedding, allocator: Allocator) void {
        self.weight.deinit(allocator);
        self.grad.deinit(allocator);
    }

    pub fn forward(self: *LearnedEmbedding, allocator: Allocator, tokens: []const u32) !Tensor {
        var out = try Tensor.init(allocator, tokens.len, self.dim);
        var r: usize = 0;
        while (r < tokens.len) : (r += 1) {
            const t = tokens[r];
            var c: usize = 0;
            while (c < self.dim) : (c += 1) {
                out.set(r, c, self.weight.get(t, c));
            }
        }
        return out;
    }

    pub fn backward(self: *LearnedEmbedding, tokens: []const u32, out_grad: Tensor) void {
        var r: usize = 0;
        while (r < tokens.len) : (r += 1) {
            const t = tokens[r];
            var c: usize = 0;
            while (c < self.dim) : (c += 1) {
                const existing = self.grad.get(t, c);
                self.grad.set(t, c, existing + out_grad.get(r, c));
            }
        }
    }
};

pub const OFTB = struct {
    fractal_scale: f32,
    dim: usize,

    pub fn init(d: usize) OFTB {
        return OFTB{
            .fractal_scale = 0.70710678,
            .dim = d,
        };
    }

    pub fn forward(self: *OFTB, allocator: Allocator, input: Tensor) !Tensor {
        var out = try Tensor.init(allocator, input.rows, input.cols);
        var r: usize = 0;
        while (r < input.rows) : (r += 1) {
            var c: usize = 0;
            while (c < input.cols) : (c += 1) {
                var mix_val: f32 = input.get(r, c);
                if (r > 0) {
                    mix_val += input.get(r - 1, c) * self.fractal_scale;
                }
                if (r < input.rows - 1) {
                    mix_val += input.get(r + 1, c) * self.fractal_scale * 0.5;
                }
                out.set(r, c, mix_val);
            }
        }
        return out;
    }

    pub fn backward(self: *OFTB, allocator: Allocator, out_grad: Tensor) !Tensor {
        var in_grad = try Tensor.init(allocator, out_grad.rows, out_grad.cols);
        var r: usize = 0;
        while (r < out_grad.rows) : (r += 1) {
            var c: usize = 0;
            while (c < out_grad.cols) : (c += 1) {
                var grad_val: f32 = out_grad.get(r, c);
                if (r > 0) {
                    grad_val += out_grad.get(r - 1, c) * self.fractal_scale * 0.5;
                }
                if (r < out_grad.rows - 1) {
                    grad_val += out_grad.get(r + 1, c) * self.fractal_scale;
                }
                in_grad.set(r, c, grad_val);
            }
        }
        return in_grad;
    }
};

pub const RSFLayer = struct {
    weight_s: Tensor,
    weight_t: Tensor,
    grad_s: Tensor,
    grad_t: Tensor,
    dim: usize,

    pub fn init(allocator: Allocator, d: usize, prng: *std.rand.DefaultPrng) !RSFLayer {
        var ws = try Tensor.init(allocator, d, d);
        var wt = try Tensor.init(allocator, d, d);
        var gs = try Tensor.init(allocator, d, d);
        var gt = try Tensor.init(allocator, d, d);
        var i: usize = 0;
        while (i < d * d) : (i += 1) {
            ws.data[i] = (prng.random().float(f32) - 0.5) * 0.1;
            wt.data[i] = (prng.random().float(f32) - 0.5) * 0.1;
        }
        return RSFLayer{
            .weight_s = ws,
            .weight_t = wt,
            .grad_s = gs,
            .grad_t = gt,
            .dim = d,
        };
    }

    pub fn deinit(self: *RSFLayer, allocator: Allocator) void {
        self.weight_s.deinit(allocator);
        self.weight_t.deinit(allocator);
        self.grad_s.deinit(allocator);
        self.grad_t.deinit(allocator);
    }

    pub fn forward(self: *RSFLayer, allocator: Allocator, input: Tensor) !Tensor {
        var out = try Tensor.init(allocator, input.rows, input.cols);
        var r: usize = 0;
        while (r < input.rows) : (r += 1) {
            var c: usize = 0;
            while (c < self.dim) : (c += 1) {
                var sum: f32 = 0.0;
                var k: usize = 0;
                while (k < self.dim) : (k += 1) {
                    sum += input.get(r, k) * self.weight_s.get(k, c);
                }
                if (sum < 0.0) sum = 0.0;
                var sum_t: f32 = 0.0;
                k = 0;
                while (k < self.dim) : (k += 1) {
                    sum_t += sum * self.weight_t.get(k, c);
                }
                out.set(r, c, sum_t);
            }
        }
        return out;
    }

    pub fn backward(self: *RSFLayer, allocator: Allocator, input: Tensor, out_grad: Tensor) !Tensor {
        var in_grad = try Tensor.init(allocator, input.rows, input.cols);
        var r: usize = 0;
        while (r < input.rows) : (r += 1) {
            var c: usize = 0;
            while (c < self.dim) : (c += 1) {
                var grad_val: f32 = 0.0;
                var k: usize = 0;
                while (k < self.dim) : (k += 1) {
                    grad_val += out_grad.get(r, k) * self.weight_t.get(c, k);
                    const update_t = self.grad_t.get(c, k) + (input.get(r, c) * out_grad.get(r, k));
                    self.grad_t.set(c, k, update_t);

                    const update_s = self.grad_s.get(c, k) + (input.get(r, c) * grad_val);
                    self.grad_s.set(c, k, update_s);
                }
                in_grad.set(r, c, grad_val);
            }
        }
        return in_grad;
    }
};

pub const NSIR = struct {
    dim: usize,
    modulation_factor: f32,

    pub fn init(d: usize) NSIR {
        return NSIR{
            .dim = d,
            .modulation_factor = 1.05,
        };
    }

    pub fn forward(self: *NSIR, allocator: Allocator, input: Tensor) !Tensor {
        var out = try Tensor.init(allocator, input.rows, input.cols);
        var r: usize = 0;
        while (r < input.rows) : (r += 1) {
            var mean: f32 = 0.0;
            var c: usize = 0;
            while (c < input.cols) : (c += 1) {
                mean += input.get(r, c);
            }
            mean /= @as(f32, @floatFromInt(input.cols));

            c = 0;
            while (c < input.cols) : (c += 1) {
                var val = input.get(r, c);
                if (val > mean) {
                    val *= self.modulation_factor;
                }
                out.set(r, c, val);
            }
        }
        return out;
    }

    pub fn backward(self: *NSIR, allocator: Allocator, out_grad: Tensor) !Tensor {
        var in_grad = try Tensor.init(allocator, out_grad.rows, out_grad.cols);
        var r: usize = 0;
        while (r < out_grad.rows) : (r += 1) {
            var c: usize = 0;
            while (c < out_grad.cols) : (c += 1) {
                in_grad.set(r, c, out_grad.get(r, c) * self.modulation_factor);
            }
        }
        return in_grad;
    }
};

pub const Projection = struct {
    weight: Tensor,
    bias: Tensor,
    grad_w: Tensor,
    grad_b: Tensor,
    vocab_size: usize,
    dim: usize,

    pub fn init(allocator: Allocator, v_size: usize, d: usize, prng: *std.rand.DefaultPrng) !Projection {
        var w = try Tensor.init(allocator, d, v_size);
        var b = try Tensor.init(allocator, 1, v_size);
        var gw = try Tensor.init(allocator, d, v_size);
        var gb = try Tensor.init(allocator, 1, v_size);
        var i: usize = 0;
        while (i < d * v_size) : (i += 1) {
            w.data[i] = (prng.random().float(f32) - 0.5) * 0.02;
        }
        return Projection{
            .weight = w,
            .bias = b,
            .grad_w = gw,
            .grad_b = gb,
            .vocab_size = v_size,
            .dim = d,
        };
    }

    pub fn deinit(self: *Projection, allocator: Allocator) void {
        self.weight.deinit(allocator);
        self.bias.deinit(allocator);
        self.grad_w.deinit(allocator);
        self.grad_b.deinit(allocator);
    }

    pub fn forward(self: *Projection, allocator: Allocator, input: Tensor) !Tensor {
        var out = try Tensor.init(allocator, input.rows, self.vocab_size);
        var r: usize = 0;
        while (r < input.rows) : (r += 1) {
            var v: usize = 0;
            while (v < self.vocab_size) : (v += 1) {
                var sum = self.bias.get(0, v);
                var c: usize = 0;
                while (c < self.dim) : (c += 1) {
                    sum += input.get(r, c) * self.weight.get(c, v);
                }
                out.set(r, v, sum);
            }
        }
        return out;
    }

    pub fn backward(self: *Projection, allocator: Allocator, input: Tensor, out_grad: Tensor) !Tensor {
        var in_grad = try Tensor.init(allocator, input.rows, input.cols);
        var r: usize = 0;
        while (r < input.rows) : (r += 1) {
            var v: usize = 0;
            while (v < self.vocab_size) : (v += 1) {
                const g = out_grad.get(r, v);
                self.grad_b.set(0, v, self.grad_b.get(0, v) + g);
                var c: usize = 0;
                while (c < self.dim) : (c += 1) {
                    self.grad_w.set(c, v, self.grad_w.get(c, v) + input.get(r, c) * g);
                    in_grad.set(r, c, in_grad.get(r, c) + g * self.weight.get(c, v));
                }
            }
        }
        return in_grad;
    }
};

pub const SFDOptimizer = struct {
    lr: f32,
    momentum: f32,

    pub fn init(learning_rate: f32, mom: f32) SFDOptimizer {
        return SFDOptimizer{ .lr = learning_rate, .momentum = mom };
    }

    pub fn updateTensor(self: *SFDOptimizer, param: *Tensor, grad: *Tensor) void {
        var i: usize = 0;
        const total = param.rows * param.cols;
        while (i < total) : (i += 1) {
            param.data[i] -= self.lr * grad.data[i];
            grad.data[i] *= self.momentum;
        }
    }

    pub fn update(self: *SFDOptimizer, embed: *LearnedEmbedding, rsf: *RSFLayer, proj: *Projection) void {
        self.updateTensor(&embed.weight, &embed.grad);
        self.updateTensor(&rsf.weight_s, &rsf.grad_s);
        self.updateTensor(&rsf.weight_t, &rsf.grad_t);
        self.updateTensor(&proj.weight, &proj.grad_w);
        self.updateTensor(&proj.bias, &proj.grad_b);
    }
};

pub const JaideModel = struct {
    embed: LearnedEmbedding,
    oftb: OFTB,
    rsf: RSFLayer,
    nsir: NSIR,
    proj: Projection,
    optim: SFDOptimizer,

    pub fn init(allocator: Allocator, vocab_size: usize, dim: usize, prng: *std.rand.DefaultPrng) !JaideModel {
        return JaideModel{
            .embed = try LearnedEmbedding.init(allocator, vocab_size, dim, prng),
            .oftb = OFTB.init(dim),
            .rsf = try RSFLayer.init(allocator, dim, prng),
            .nsir = NSIR.init(dim),
            .proj = try Projection.init(allocator, vocab_size, dim, prng),
            .optim = SFDOptimizer.init(0.001, 0.9),
        };
    }

    pub fn deinit(self: *JaideModel, allocator: Allocator) void {
        self.embed.deinit(allocator);
        self.rsf.deinit(allocator);
        self.proj.deinit(allocator);
    }

    pub fn trainStep(self: *JaideModel, allocator: Allocator, tokens: []const u32, targets: []const u32) !f32 {
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        const a = arena.allocator();

        const emb_out = try self.embed.forward(a, tokens);
        const oftb_out = try self.oftb.forward(a, emb_out);
        const rsf_out = try self.rsf.forward(a, oftb_out);
        const nsir_out = try self.nsir.forward(a, rsf_out);
        const logits = try self.proj.forward(a, nsir_out);

        var loss: f32 = 0.0;
        var grad_logits = try Tensor.init(a, logits.rows, logits.cols);

        var r: usize = 0;
        while (r < logits.rows) : (r += 1) {
            var max_logit = logits.get(r, 0);
            var c: usize = 1;
            while (c < logits.cols) : (c += 1) {
                if (logits.get(r, c) > max_logit) max_logit = logits.get(r, c);
            }

            var sum_exp: f32 = 0.0;
            c = 0;
            while (c < logits.cols) : (c += 1) {
                sum_exp += math.exp(logits.get(r, c) - max_logit);
            }

            const target_idx = targets[r];
            c = 0;
            while (c < logits.cols) : (c += 1) {
                const prob = math.exp(logits.get(r, c) - max_logit) / sum_exp;
                if (c == target_idx) {
                    loss -= math.log(prob + 1e-8);
                    grad_logits.set(r, c, prob - 1.0);
                } else {
                    grad_logits.set(r, c, prob);
                }
            }
        }
        loss /= @as(f32, @floatFromInt(logits.rows));

        const grad_nsir = try self.proj.backward(a, nsir_out, grad_logits);
        const grad_rsf = try self.nsir.backward(a, grad_nsir);
        const grad_oftb = try self.rsf.backward(a, oftb_out, grad_rsf);
        const grad_emb = try self.oftb.backward(a, grad_oftb);
        self.embed.backward(tokens, grad_emb);

        self.optim.update(&self.embed, &self.rsf, &self.proj);

        return loss;
    }

    pub fn generatePipeline(self: *JaideModel, allocator: Allocator, prompt: []const u32, max_len: usize) ![]u32 {
        var result = std.ArrayList(u32).init(allocator);
        try result.appendSlice(prompt);

        var step: usize = 0;
        while (step < max_len) : (step += 1) {
            var arena = std.heap.ArenaAllocator.init(allocator);
            const a = arena.allocator();

            const current_tokens = result.items;
            const emb_out = try self.embed.forward(a, current_tokens);
            const oftb_out = try self.oftb.forward(a, emb_out);
            const rsf_out = try self.rsf.forward(a, oftb_out);
            const nsir_out = try self.nsir.forward(a, rsf_out);
            const logits = try self.proj.forward(a, nsir_out);

            const last_row = logits.rows - 1;
            var best_idx: u32 = 0;
            var best_val = logits.get(last_row, 0);
            var v: u32 = 1;
            while (v < self.proj.vocab_size) : (v += 1) {
                const val = logits.get(last_row, v);
                if (val > best_val) {
                    best_val = val;
                    best_idx = v;
                }
            }

            try result.append(best_idx);
            arena.deinit();
        }

        return result.toOwnedSlice();
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var prng = std.rand.DefaultPrng.init(42);

    var model = try JaideModel.init(allocator, 1000, 128, &prng);
    defer model.deinit(allocator);

